typedef struct {
  int r, c;
} Pos;

static bool contains(Pos *arr, int n, int r, int c) {
  for (int i = 0; i < n; i++) {
    if (arr[i].r == r && arr[i].c == c) return true;
  }
  return false;
}

char **printKMoves(int K, int *returnSize) {
  Pos black[200000], visited[200000];
  int bn = 0, vn = 0;
  int dr[] = {0, 1, 0, -1};
  int dc[] = {1, 0, -1, 0};
  int dir = 0, r = 0, c = 0;
  visited[vn].r = 0;
  visited[vn].c = 0;
  vn++;
  for (int k = 0; k < K; k++) {
    if (!contains(black, bn, r, c)) {
      black[bn].r = r;
      black[bn].c = c;
      bn++;
      dir = (dir + 1) % 4;
    } else {
      for (int i = 0; i < bn; i++) {
        if (black[i].r == r && black[i].c == c) {
          black[i] = black[bn - 1];
          bn--;
          break;
        }
      }
      dir = (dir + 3) % 4;
    }
    r += dr[dir];
    c += dc[dir];
    if (!contains(visited, vn, r, c)) {
      visited[vn].r = r;
      visited[vn].c = c;
      vn++;
    }
  }
  int minR = 0, maxR = 0, minC = 0, maxC = 0;
  for (int i = 0; i < vn; i++) {
    if (visited[i].r < minR) minR = visited[i].r;
    if (visited[i].r > maxR) maxR = visited[i].r;
    if (visited[i].c < minC) minC = visited[i].c;
    if (visited[i].c > maxC) maxC = visited[i].c;
  }
  int rows = maxR - minR + 1, cols = maxC - minC + 1;
  char **res = (char **)malloc(sizeof(char *) * rows);
  const char letters[] = "RDLU";
  for (int i = 0; i < rows; i++) {
    res[i] = (char *)calloc(cols + 1, 1);
    for (int j = 0; j < cols; j++) {
      int rr = minR + i, cc = minC + j;
      if (rr == r && cc == c) {
        res[i][j] = letters[dir];
      } else if (contains(black, bn, rr, cc)) {
        res[i][j] = 'X';
      } else {
        res[i][j] = '_';
      }
    }
  }
  *returnSize = rows;
  return res;
}

class Solution {
public:
  vector<string> printKMoves(int K) {
    int dr[] = {0, 1, 0, -1};
    int dc[] = {1, 0, -1, 0};
    int dir = 0, r = 0, c = 0;
    set<pair<int, int>> black;
    set<pair<int, int>> visited;
    visited.insert({0, 0});
    for (int k = 0; k < K; k++) {
      auto p = make_pair(r, c);
      if (!black.count(p)) {
        black.insert(p);
        dir = (dir + 1) % 4;
      } else {
        black.erase(p);
        dir = (dir + 3) % 4;
      }
      r += dr[dir];
      c += dc[dir];
      visited.insert({r, c});
    }
    int minR = 0, maxR = 0, minC = 0, maxC = 0;
    for (auto &p : visited) {
      minR = min(minR, p.first);
      maxR = max(maxR, p.first);
      minC = min(minC, p.second);
      maxC = max(maxC, p.second);
    }
    const string letters = "RDLU";
    vector<string> res;
    for (int i = minR; i <= maxR; i++) {
      string row;
      for (int j = minC; j <= maxC; j++) {
        if (i == r && j == c) {
          row += letters[dir];
        } else if (black.count({i, j})) {
          row += 'X';
        } else {
          row += '_';
        }
      }
      res.push_back(row);
    }
    return res;
  }
};

type Pos struct{ r, c int }

func printKMoves(K int) []string {
	dr := []int{0, 1, 0, -1}
	dc := []int{1, 0, -1, 0}
	dir, r, c := 0, 0, 0
	black := map[Pos]bool{}
	visited := map[Pos]bool{{0, 0}: true}
	for k := 0; k < K; k++ {
		p := Pos{r, c}
		if !black[p] {
			black[p] = true
			dir = (dir + 1) % 4
		} else {
			delete(black, p)
			dir = (dir + 3) % 4
		}
		r += dr[dir]
		c += dc[dir]
		visited[Pos{r, c}] = true
	}
	minR, maxR, minC, maxC := 0, 0, 0, 0
	for p := range visited {
		if p.r < minR {
			minR = p.r
		}
		if p.r > maxR {
			maxR = p.r
		}
		if p.c < minC {
			minC = p.c
		}
		if p.c > maxC {
			maxC = p.c
		}
	}
	letters := "RDLU"
	res := []string{}
	for i := minR; i <= maxR; i++ {
		row := []byte{}
		for j := minC; j <= maxC; j++ {
			if i == r && j == c {
				row = append(row, letters[dir])
			} else if black[Pos{i, j}] {
				row = append(row, 'X')
			} else {
				row = append(row, '_')
			}
		}
		res = append(res, string(row))
	}
	return res
}

class Solution {
  public String[] printKMoves(int K) {
    int[] dr = { 0, 1, 0, -1 };
    int[] dc = { 1, 0, -1, 0 };
    int dir = 0, r = 0, c = 0;
    Set<String> black = new HashSet<>();
    Set<String> visited = new HashSet<>();
    visited.add("0,0");
    for (int k = 0; k < K; k++) {
      String p = r + "," + c;
      if (!black.contains(p)) {
        black.add(p);
        dir = (dir + 1) % 4;
      } else {
        black.remove(p);
        dir = (dir + 3) % 4;
      }
      r += dr[dir];
      c += dc[dir];
      visited.add(r + "," + c);
    }
    int minR = 0, maxR = 0, minC = 0, maxC = 0;
    for (String p : visited) {
      String[] parts = p.split(",");
      int pr = Integer.parseInt(parts[0]);
      int pc = Integer.parseInt(parts[1]);
      minR = Math.min(minR, pr);
      maxR = Math.max(maxR, pr);
      minC = Math.min(minC, pc);
      maxC = Math.max(maxC, pc);
    }
    String letters = "RDLU";
    String[] res = new String[maxR - minR + 1];
    for (int i = minR; i <= maxR; i++) {
      StringBuilder row = new StringBuilder();
      for (int j = minC; j <= maxC; j++) {
        if (i == r && j == c) {
          row.append(letters.charAt(dir));
        } else if (black.contains(i + "," + j)) {
          row.append('X');
        } else {
          row.append('_');
        }
      }
      res[i - minR] = row.toString();
    }
    return res;
  }
}

class Solution:
    def printKMoves(self, K: int) -> List[str]:
        dr = [0, 1, 0, -1]
        dc = [1, 0, -1, 0]
        d, r, c = 0, 0, 0
        black = set()
        visited = {(0, 0)}
        for _ in range(K):
            p = (r, c)
            if p not in black:
                black.add(p)
                d = (d + 1) % 4
            else:
                black.discard(p)
                d = (d + 3) % 4
            r += dr[d]
            c += dc[d]
            visited.add((r, c))
        min_r = min(p[0] for p in visited)
        max_r = max(p[0] for p in visited)
        min_c = min(p[1] for p in visited)
        max_c = max(p[1] for p in visited)
        letters = "RDLU"
        res = []
        for i in range(min_r, max_r + 1):
            row = []
            for j in range(min_c, max_c + 1):
                if (i, j) == (r, c):
                    row.append(letters[d])
                elif (i, j) in black:
                    row.append("X")
                else:
                    row.append("_")
            res.append("".join(row))
        return res

impl Solution {
  pub fn print_k_moves(k: i32) -> Vec<String> {
    let dr = [0i32, 1, 0, -1];
    let dc = [1i32, 0, -1, 0];
    let (mut dir, mut r, mut c) = (0usize, 0i32, 0i32);
    let mut black: HashSet<(i32, i32)> = HashSet::new();
    let mut visited: HashSet<(i32, i32)> = HashSet::new();
    visited.insert((0, 0));
    for _ in 0..k {
      if !black.contains(&(r, c)) {
        black.insert((r, c));
        dir = (dir + 1) % 4;
      } else {
        black.remove(&(r, c));
        dir = (dir + 3) % 4;
      }
      r += dr[dir];
      c += dc[dir];
      visited.insert((r, c));
    }
    let (mut min_r, mut max_r, mut min_c, mut max_c) = (0, 0, 0, 0);
    for &(pr, pc) in &visited {
      min_r = min_r.min(pr);
      max_r = max_r.max(pr);
      min_c = min_c.min(pc);
      max_c = max_c.max(pc);
    }
    let letters = ['R', 'D', 'L', 'U'];
    let mut res = vec![];
    for i in min_r..=max_r {
      let mut row = String::new();
      for j in min_c..=max_c {
        if i == r && j == c {
          row.push(letters[dir]);
        } else if black.contains(&(i, j)) {
          row.push('X');
        } else {
          row.push('_');
        }
      }
      res.push(row);
    }
    res
  }
}

const printKMoves = (K: number): string[] => {
  const dr = [0, 1, 0, -1];
  const dc = [1, 0, -1, 0];
  let dir = 0;
  let r = 0;
  let c = 0;
  const black = new Set<string>();
  const visited = new Set<string>(['0,0']);
  for (let k = 0; k < K; k++) {
    const p = `${r},${c}`;
    if (!black.has(p)) {
      black.add(p);
      dir = (dir + 1) % 4;
    } else {
      black.delete(p);
      dir = (dir + 3) % 4;
    }
    r += dr[dir];
    c += dc[dir];
    visited.add(`${r},${c}`);
  }
  let minR = 0;
  let maxR = 0;
  let minC = 0;
  let maxC = 0;
  for (const p of visited) {
    const [pr, pc] = p.split(',').map(Number);
    minR = Math.min(minR, pr);
    maxR = Math.max(maxR, pr);
    minC = Math.min(minC, pc);
    maxC = Math.max(maxC, pc);
  }
  const letters = 'RDLU';
  const res: string[] = [];
  for (let i = minR; i <= maxR; i++) {
    let row = '';
    for (let j = minC; j <= maxC; j++) {
      if (i === r && j === c) row += letters[dir];
      else if (black.has(`${i},${j}`)) row += 'X';
      else row += '_';
    }
    res.push(row);
  }
  return res;
};
